O=Path('sources/audits/unit18-grammar');p=O/'candidate-models.json';d=json.loads(p.read_text(encoding='utf8'));(O/'candidate-models-v5-witness.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8');changes=[]
