p=O/'build-verbal-systems.py';s=p.read_text(encoding='utf8');s='\n'.join(line for line in s.splitlines()if "'corrective-preterite6'"not in line)+'\n';p.write_text(s,encoding='utf8')
p=O/'build-bindings.py';s=p.read_text(encoding='utf8').replace('fand:it3s','funde:it3s').replace("'model_version':'v5'","'model_version':'v6'");p.write_text(s,encoding='utf8')
(O/'withdrawn-findan-finding.json').write_text(json.dumps({'status':'withdrawn; not a correction to any earlier artifact','initial_hypothesis':'The earlier findan-pret-3-sg funde record was provisionally misidentified as an error by overgeneralizing the regular first/third singular pattern.','resolution':'Personally viewed Cook printed62/PDF78: findan likewise forms third singular past indicative as funde, indeed the usual form. Personally viewed Wright printed258/PDF278: beside fand occurs funde, the second-person form also used for first and third. Earlier ch04 correctly teaches this exception. Current47.5 selects prior funde; fand is valid but is not newly assigned here.','prior_locations':['chapters/ch04/answer-key.md:5','chapters/ch04/answer-key.md:291','chapters/ch04/answer-key.md:298','chapters/ch04/coverage.json:u04-findan-exception'],'evidence':['sources/audits/unit14-grammar/fb-p62.png','sources/audits/unit04-grammar/wright-p258-pdf278.png'],'preservation':'No earlier file, form, analysis, sense or milestone changed; the provisional extra Unit18 review system was removed before contract.'},ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('v6 changes',len(changes))
